async(page)=>{
 const root='D:/7rd_semester/pbl6_src/ctsv/prototypes/p11-signing',shots=[];let assertions=0;const errors=[];page.on('pageerror',e=>errors.push(e.message));
 const assert=(x,m)=>{if(!x)throw Error(m);assertions++};
 const shot=async(n)=>{await page.screenshot({path:root+'/screenshots/'+n+'.png',fullPage:true});shots.push(n)};
 const rendered=async()=>{await page.waitForFunction(()=>Number(document.querySelector('#pdf-canvas')?.dataset.renderedPage)===window.p11Prototype.page);await page.waitForTimeout(150)};
 const reset=async()=>{await page.locator('#reset').click();await page.locator('#confirm-reset').click();await page.goto('http://127.0.0.1:5178/#document/bb');await page.locator('#pdf-file').setInputFiles(root+'/assets/bb.pdf');await page.locator('#content-checked').check();await page.locator('#save-pdf').click();await rendered()};
 const region=async(pageNumber=2)=>{
  await page.locator('#page').fill(''+pageNumber);await page.locator('#page').dispatchEvent('change');await rendered();await page.locator('#choose').click();
  await page.locator('.canvas-scroll').evaluate(e=>e.scrollTop=0);const b=await page.locator('#overlay').boundingBox();let x=50,y=Math.min(250,b.height/2),w=125,h=40;
  await page.mouse.move(b.x+x,b.y+y);await page.mouse.down();await page.mouse.move(b.x+x+w,b.y+y+h,{steps:10});await page.mouse.up();assert((await page.evaluate(()=>window.p11Prototype.geometry))?.page===pageNumber,'selected geometry at requested page');
 };
 const fault=async(value)=>{await page.locator('details.test-lab').evaluate(e=>e.open=true);await page.locator('#fault').selectOption(value);await page.locator('#sign').click();await page.locator('#confirm-sign').click();await page.waitForFunction(()=>!document.querySelector('dialog').open);await rendered()};
 await page.goto('http://127.0.0.1:5178');await page.evaluate(()=>localStorage.setItem('p11-walkthrough-result',localStorage.getItem('ctsv-p11-prototype-v1')));
 await reset();await page.locator('#replace').click();await shot('38-cv-thay-pdf-chuan-bi');await page.locator('#pdf-file').setInputFiles(root+'/assets/bb-revised.pdf');await page.locator('#content-checked').check();await page.locator('#save-pdf').click();await rendered();assert(await page.evaluate(()=>window.p11Prototype.state.docs.bb.version===2),'new document version');await page.locator('#view-history').click();await shot('39-cv-phien-ban-cu-duoc-giu');await page.getByRole('button',{name:'Xem bản cũ',exact:true}).click();await page.waitForTimeout(250);assert(await page.locator('#history-canvas').evaluate(e=>e.height>200),'old PDF preview loaded');await shot('40-cv-xem-pdf-cu-readonly');await page.getByRole('button',{name:'Đóng',exact:true}).click();await page.getByRole('tab',{name:'Tài liệu & ký số',exact:true}).click();await rendered();
 await region(3);let g=await page.evaluate(()=>window.p11Prototype.geometry);assert(g.x>=0&&g.y>=0,'rotation PDF points');await shot('41-pdf-trang-xoay-90');await page.locator('#rotate').click();await page.waitForTimeout(200);assert(JSON.stringify(await page.evaluate(()=>window.p11Prototype.geometry))===JSON.stringify(g),'manual rotation preserves points');await shot('42-xoay-view-khong-doi-vung-pdf');
 await region(4);g=await page.evaluate(()=>window.p11Prototype.geometry);assert(g.x>=20&&g.y>=30,'crop offsets respected');await shot('43-pdf-cropbox-co-offset');
 await fault('stale');assert(await page.evaluate(()=>window.p11Prototype.geometry===null&&window.p11Prototype.state.docs.bb.steps.length===0),'stale clears region and no signature');await shot('44-phien-ban-cu-khong-duoc-ky');
 await region();await fault('download');assert(await page.evaluate(()=>window.p11Prototype.state.docs.bb.status==='download'&&window.p11Prototype.state.docs.bb.steps.length===0),'download failure never advances');assert(await page.locator('#sign').count()===0,'no duplicate sign button');await shot('45-ca-thanh-cong-tai-pdf-loi');
 await page.locator('#recover').click();await shot('46-cv-khoi-phuc-khong-ky-lai');await page.waitForFunction(()=>!document.querySelector('dialog').open);await rendered();assert(await page.evaluate(()=>window.p11Prototype.state.docs.bb.steps.length===1),'recovery commits first output');await shot('47-khoi-phuc-da-luu-cho-pht');
 await reset();await region();await fault('storage');assert(await page.evaluate(()=>window.p11Prototype.state.docs.bb.status==='storage'&&window.p11Prototype.state.docs.bb.steps.length===0),'storage failure never completes');await shot('48-loi-luu-ket-qua-ctsv');await page.locator('#recover').click();await page.waitForFunction(()=>!document.querySelector('dialog').open);await rendered();assert(await page.evaluate(()=>window.p11Prototype.state.docs.bb.steps.length===1),'storage recovery completes');await shot('49-luu-lai-ket-qua-thanh-cong');
 await reset();await region();await fault('unknown');assert(await page.evaluate(()=>window.p11Prototype.state.docs.bb.status==='unknown'),'unknown state');assert(await page.locator('#sign').count()===0&&await page.locator('#recover').count()===0&&await page.locator('#replace').count()===0,'unknown no unsafe retry or replace');await shot('50-timeout-ky-chua-ro-ket-qua');await page.reload();await rendered();assert(await page.evaluate(()=>window.p11Prototype.state.docs.bb.status==='unknown'),'unknown survives refresh');await shot('51-refresh-giu-unknown');
 await reset();await region();await fault('certificate');assert(await page.evaluate(()=>window.p11Prototype.state.docs.bb.status==='failed'&&window.p11Prototype.state.docs.bb.steps.length===0),'certificate failure no signing');await shot('52-chung-thu-chua-san-sang');
 await reset();await page.setViewportSize({width:390,height:844});await page.reload();await rendered();await region();assert(await page.evaluate(()=>window.p11Prototype.geometry.width>0),'mobile region selection');await shot('53-mobile-chon-vung-ky');await page.locator('#sign').click();await shot('54-mobile-xac-nhan-ky');await page.getByRole('button',{name:'Quay lại',exact:true}).click();assert(await page.evaluate(()=>window.p11Prototype.state.docs.bb.steps.length===0),'cancel confirmation does not sign');
 assert(errors.length===0,'no console page errors '+errors.join(';'));
 await page.evaluate(()=>{localStorage.setItem('ctsv-p11-prototype-v1',localStorage.getItem('p11-walkthrough-result'));localStorage.removeItem('p11-walkthrough-result')});await page.setViewportSize({width:1440,height:1100});await page.goto('http://127.0.0.1:5178/#list');await page.reload();
 return {assertions,shots,errors,scope:'PROTOTYPE SIMULATED. No CA/backend calls.'};
}
